import {
  afterNextRender,
  computed,
  DestroyRef,
  effect,
  inject,
  signal,
  untracked,
  type Signal,
} from "@angular/core";
import {
  createTree,
  type FeatureImplementation,
  type ItemInstance,
  type TreeConfig,
  type TreeInstance,
  type TreeState,
} from "@headless-tree/core";
import { buildTreeConfig, type TreeControllerOptions } from "@/ui/tree-controller";

/** A headless-tree instance with its visible items as a signal. */
export type KoTreeHandle<T> = {
  tree: TreeInstance<T>;
  /** The visible items, in order; a new array whenever the tree's state changes. */
  items: Signal<ItemInstance<T>[]>;
  /** Re-reads the options (a new item list, say) and rebuilds the visible items. */
  rebuild(): void;
};

/**
 * The Angular counterpart of `@headless-tree/react`'s `useTree`, over `buildTreeConfig`.
 * The tree's state is mirrored into a signal, and every state change (through `setState`,
 * or a sub-state update a caller's own `set*` handler took over) bumps a version that
 * `items` is computed from, so a zoneless template re-renders. The options are re-read
 * whenever a signal they read changes; a structural change still needs `rebuild()`, as
 * React's `rebuildTree()` does. Call it in an injection context.
 */
export function injectTreeController<T>(options: () => TreeControllerOptions<T>): KoTreeHandle<T> {
  const destroyRef = inject(DestroyRef);
  const version = signal(0);
  const bump = () => version.update((v) => v + 1);

  const state = signal<TreeState<T>>({} as TreeState<T>);

  /** Catches every sub-state update, also those a caller's `set*` handler took over. */
  const signalsFeature: FeatureImplementation<T> = {
    key: "ko-signals",
    treeInstance: {
      applySubStateUpdate: ({ tree, prev }, ...args: unknown[]) => {
        (prev as (...a: unknown[]) => void)?.(...args);
        state.set({ ...tree.getState() });
        bump();
      },
    },
  };

  const configure = (opts: TreeControllerOptions<T>): TreeConfig<T> => {
    const config = buildTreeConfig(opts);
    return { ...config, features: [...(config.features ?? []), signalsFeature] };
  };

  const sync = (opts: TreeControllerOptions<T>) => {
    const next = configure(opts);
    tree.setConfig((prev) => ({
      ...prev,
      ...next,
      state: { ...untracked(state), ...next.state },
      setState: (updated) => {
        state.set({ ...(updated as TreeState<T>) });
        bump();
        next.setState?.(updated);
      },
    }));
  };

  const tree = createTree(configure(untracked(options)));
  state.set({ ...tree.getState() });
  sync(untracked(options));

  effect(() => {
    const opts = options();
    untracked(() => {
      sync(opts);
      bump();
    });
  });

  afterNextRender(() => {
    tree.setMounted(true);
    tree.rebuildTree();
    bump();
  });

  destroyRef.onDestroy(() => tree.setMounted(false));

  const items = computed(() => {
    version();
    return [...tree.getItems()];
  });

  return {
    tree,
    items,
    rebuild: () => {
      sync(untracked(options));
      tree.rebuildTree();
      bump();
    },
  };
}

import type { FeatureImplementation } from "@headless-tree/core";

/**
 * Replaces headless-tree's `updateDomFocus`, which calls `element.focus()`
 * without `preventScroll` (the browser then scrolls the row on its own, outside
 * the app's reveal logic) and, if the row is not mounted within 500 ms, moves
 * focus to the first row — jumping the list to the top. Register it last.
 */
export const preventScrollFocusFeature: FeatureImplementation = {
  key: "prevent-scroll-focus",
  treeInstance: {
    updateDomFocus: ({ tree }) => {
      requestAnimationFrame(() => {
        tree.getFocusedItem()?.getElement()?.focus({ preventScroll: true });
      });
    },
  },
};

/**
 * headless-tree hands out React-shaped props (`item.getProps()`, `tree.getContainerProps()`,
 * `item.getDragHandleProps()`): camelCase DOM props, a `style` object, `onClick`-style
 * handlers and a `ref` callback. These turn that bag into what an Angular directive applies
 * through `Renderer2`: attributes, styles, DOM listeners and the ref.
 */

export type TreeElementProps = Record<string, unknown>;

export type TreeListener = (event: Event) => unknown;

export type TreePropsBinding = {
  /** Attribute name to value; `null` means the attribute is not set. */
  attributes: Record<string, string | null>;
  /** Kebab-case style property to value. */
  styles: Record<string, string>;
  /** DOM event name to handler. */
  listeners: Record<string, TreeListener>;
  ref?: (element: HTMLElement | null) => void;
};

const EVENT_ALIASES: Record<string, string> = { doubleclick: "dblclick" };
const ATTRIBUTE_ALIASES: Record<string, string> = { className: "class", htmlFor: "for" };
/** Attributes whose boolean values are written out as "true"/"false", like ARIA. */
const ENUMERATED = new Set(["draggable", "spellcheck", "contenteditable"]);
/** Style properties a plain number is written to without a unit. */
const UNITLESS = new Set(["z-index", "opacity", "flex", "flex-grow", "flex-shrink", "order"]);

/** `onKeyDown` → `keydown`; `null` for a prop that is not an event handler. */
export function eventNameOf(prop: string): string | null {
  const match = /^on([A-Z][A-Za-z]*)$/.exec(prop);
  if (!match) return null;
  const name = match[1].toLowerCase();
  return EVENT_ALIASES[name] ?? name;
}

/** `tabIndex` → `tabindex`, `className` → `class`; dashed names stay as they are. */
export function attributeNameOf(prop: string): string {
  if (prop in ATTRIBUTE_ALIASES) return ATTRIBUTE_ALIASES[prop];
  return prop.includes("-") ? prop : prop.toLowerCase();
}

/** The attribute value React would render, or `null` when it renders none. */
export function attributeValueOf(name: string, value: unknown): string | null {
  if (value === null || value === undefined) return null;
  if (typeof value === "boolean") {
    if (name.startsWith("aria-") || name.startsWith("data-") || ENUMERATED.has(name)) {
      return String(value);
    }
    return value ? "" : null;
  }
  return String(value);
}

const kebab = (prop: string) => prop.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);

/** A React style object as kebab-case properties; empty values are left out. */
export function styleEntriesOf(style: unknown): Record<string, string> {
  const out: Record<string, string> = {};
  if (!style || typeof style !== "object") return out;
  for (const [key, value] of Object.entries(style as Record<string, unknown>)) {
    if (value === null || value === undefined || value === "") continue;
    const prop = kebab(key);
    out[prop] = typeof value === "number" && !UNITLESS.has(prop) ? `${value}px` : String(value);
  }
  return out;
}

/** Splits a headless-tree props bag into attributes, styles, listeners and the ref. */
export function toPropsBinding(props: TreeElementProps): TreePropsBinding {
  const binding: TreePropsBinding = { attributes: {}, styles: {}, listeners: {} };
  for (const [prop, value] of Object.entries(props)) {
    if (prop === "ref") {
      if (typeof value === "function") binding.ref = value as TreePropsBinding["ref"];
      continue;
    }
    if (prop === "style") {
      binding.styles = styleEntriesOf(value);
      continue;
    }
    if (typeof value === "function") {
      const event = eventNameOf(prop);
      if (event) binding.listeners[event] = value as TreeListener;
      continue;
    }
    const name = attributeNameOf(prop);
    binding.attributes[name] = attributeValueOf(name, value);
  }
  return binding;
}

/** The keys `previous` had that `next` no longer sets, so they can be removed. */
export function staleKeys(
  previous: Record<string, string | null> | undefined,
  next: Record<string, string | null>,
): string[] {
  if (!previous) return [];
  return Object.keys(previous).filter((key) => next[key] === undefined || next[key] === null);
}

/** The part of `Renderer2` the applier writes through. */
export type TreePropsRenderer = {
  setAttribute(el: unknown, name: string, value: string): void;
  removeAttribute(el: unknown, name: string): void;
  setStyle(el: unknown, style: string, value: unknown, flags?: number): void;
  removeStyle(el: unknown, style: string, flags?: number): void;
  listen(target: unknown, eventName: string, callback: (event: unknown) => unknown): () => void;
};

/** `RendererStyleFlags2.DashCase`: the style names given are kebab-case. */
const DASH_CASE = 2;

/**
 * Applies one props bag after another to the same element: stale attributes and styles are
 * removed, every listener is swapped for the new closure, and the ref is told about the
 * element (and told `null` when a different ref takes over, or on `clear`).
 */
export class TreePropsApplier {
  private previous?: TreePropsBinding;
  private unlisten: (() => void)[] = [];

  constructor(
    private readonly element: HTMLElement,
    private readonly renderer: TreePropsRenderer,
  ) {}

  apply(props: TreeElementProps): void {
    const { element, renderer, previous } = this;
    const next = toPropsBinding(props);
    this.removeListeners();

    for (const name of staleKeys(previous?.attributes, next.attributes)) {
      renderer.removeAttribute(element, name);
    }
    for (const [name, value] of Object.entries(next.attributes)) {
      if (value !== null) renderer.setAttribute(element, name, value);
    }
    for (const prop of staleKeys(previous?.styles, next.styles)) {
      renderer.removeStyle(element, prop, DASH_CASE);
    }
    for (const [prop, value] of Object.entries(next.styles)) {
      renderer.setStyle(element, prop, value, DASH_CASE);
    }
    for (const [event, handler] of Object.entries(next.listeners)) {
      this.unlisten.push(renderer.listen(element, event, handler as (event: unknown) => unknown));
    }
    if (previous?.ref && previous.ref !== next.ref) previous.ref(null);
    next.ref?.(element);
    this.previous = next;
  }

  /** Removes the listeners and tells the ref the element is gone. */
  clear(): void {
    this.removeListeners();
    this.previous?.ref?.(null);
    this.previous = undefined;
  }

  private removeListeners(): void {
    for (const off of this.unlisten) off();
    this.unlisten = [];
  }
}

import { describe, expect, it } from "vitest";
import {
  attributeNameOf,
  attributeValueOf,
  eventNameOf,
  staleKeys,
  styleEntriesOf,
  toPropsBinding,
  TreePropsApplier,
} from "./tree-props";

describe("eventNameOf", () => {
  it("maps React handler names to DOM event names", () => {
    expect(eventNameOf("onClick")).toBe("click");
    expect(eventNameOf("onKeyDown")).toBe("keydown");
    expect(eventNameOf("onDragStart")).toBe("dragstart");
    expect(eventNameOf("onDragOver")).toBe("dragover");
    expect(eventNameOf("onDoubleClick")).toBe("dblclick");
  });

  it("is null for a prop that is not a handler", () => {
    expect(eventNameOf("role")).toBeNull();
    expect(eventNameOf("once")).toBeNull();
    expect(eventNameOf("on")).toBeNull();
  });
});

describe("attributeNameOf", () => {
  it("lowercases camelCase DOM props and keeps dashed names", () => {
    expect(attributeNameOf("tabIndex")).toBe("tabindex");
    expect(attributeNameOf("className")).toBe("class");
    expect(attributeNameOf("htmlFor")).toBe("for");
    expect(attributeNameOf("aria-expanded")).toBe("aria-expanded");
    expect(attributeNameOf("data-tree-toggle")).toBe("data-tree-toggle");
  });
});

describe("attributeValueOf", () => {
  it("drops null and undefined, as React does", () => {
    expect(attributeValueOf("aria-expanded", undefined)).toBeNull();
    expect(attributeValueOf("role", null)).toBeNull();
  });

  it("writes booleans as strings on ARIA, data and enumerated attributes", () => {
    expect(attributeValueOf("aria-expanded", false)).toBe("false");
    expect(attributeValueOf("data-open", true)).toBe("true");
    expect(attributeValueOf("draggable", true)).toBe("true");
  });

  it("treats other booleans as present or absent", () => {
    expect(attributeValueOf("disabled", true)).toBe("");
    expect(attributeValueOf("disabled", false)).toBeNull();
  });

  it("stringifies numbers and strings", () => {
    expect(attributeValueOf("tabindex", -1)).toBe("-1");
    expect(attributeValueOf("aria-level", 2)).toBe("2");
    expect(attributeValueOf("role", "treeitem")).toBe("treeitem");
  });
});

describe("styleEntriesOf", () => {
  it("kebab-cases keys, adds px to plain numbers and drops empty values", () => {
    expect(
      styleEntriesOf({ pointerEvents: "none", top: 4, zIndex: 2, display: undefined }),
    ).toEqual({ "pointer-events": "none", top: "4px", "z-index": "2" });
  });

  it("is empty for a missing style", () => {
    expect(styleEntriesOf(undefined)).toEqual({});
  });
});

describe("toPropsBinding", () => {
  it("splits headless-tree props into attributes, styles, listeners and the ref", () => {
    const ref = () => undefined;
    const onClick = () => undefined;
    const onDragStart = () => undefined;
    const binding = toPropsBinding({
      ref,
      role: "treeitem",
      tabIndex: 0,
      "aria-expanded": undefined,
      "aria-selected": "true",
      draggable: true,
      style: { position: "relative" },
      onClick,
      onDragStart,
    });
    expect(binding.ref).toBe(ref);
    expect(binding.attributes).toEqual({
      role: "treeitem",
      tabindex: "0",
      "aria-expanded": null,
      "aria-selected": "true",
      draggable: "true",
    });
    expect(binding.styles).toEqual({ position: "relative" });
    expect(binding.listeners).toEqual({ click: onClick, dragstart: onDragStart });
  });

  it("ignores functions that are not handlers", () => {
    const binding = toPropsBinding({ getThing: () => 1 });
    expect(binding.attributes).toEqual({});
    expect(binding.listeners).toEqual({});
  });
});

describe("staleKeys", () => {
  it("lists the keys the previous binding set that the next one no longer sets", () => {
    expect(staleKeys({ a: "1", b: "2", c: null }, { a: "1", b: null })).toEqual(["b", "c"]);
    expect(staleKeys(undefined, { a: "1" })).toEqual([]);
  });
});

describe("TreePropsApplier", () => {
  function fakeRenderer() {
    const attributes = new Map<string, string>();
    const styles = new Map<string, string>();
    const listeners = new Map<string, Set<(event: unknown) => unknown>>();
    const renderer = {
      setAttribute: (_: unknown, name: string, value: string) => void attributes.set(name, value),
      removeAttribute: (_: unknown, name: string) => void attributes.delete(name),
      setStyle: (_: unknown, name: string, value: unknown) => void styles.set(name, String(value)),
      removeStyle: (_: unknown, name: string) => void styles.delete(name),
      listen: (_: unknown, event: string, handler: (event: unknown) => unknown) => {
        const set = listeners.get(event) ?? new Set();
        set.add(handler);
        listeners.set(event, set);
        return () => set.delete(handler);
      },
    };
    const fire = (event: string) => [...(listeners.get(event) ?? [])].forEach((h) => h({}));
    return { renderer, attributes, styles, fire };
  }

  it("applies attributes, styles, listeners and the ref", () => {
    const { renderer, attributes, styles, fire } = fakeRenderer();
    const element = {} as HTMLElement;
    const refs: unknown[] = [];
    const clicks: string[] = [];
    const applier = new TreePropsApplier(element, renderer);
    const ref = (el: unknown) => refs.push(el);
    applier.apply({
      ref,
      role: "treeitem",
      style: { paddingLeft: 8 },
      onClick: () => clicks.push("a"),
    });
    expect(attributes.get("role")).toBe("treeitem");
    expect(styles.get("padding-left")).toBe("8px");
    fire("click");
    expect(clicks).toEqual(["a"]);
    expect(refs).toEqual([element]);
  });

  it("removes stale attributes and styles, and swaps the listeners on re-apply", () => {
    const { renderer, attributes, styles, fire } = fakeRenderer();
    const clicks: string[] = [];
    const applier = new TreePropsApplier({} as HTMLElement, renderer);
    applier.apply({
      "aria-expanded": true,
      tabIndex: 0,
      style: { top: 1 },
      onClick: () => clicks.push("old"),
    });
    applier.apply({ "aria-expanded": undefined, tabIndex: -1, onClick: () => clicks.push("new") });
    expect(attributes.has("aria-expanded")).toBe(false);
    expect(attributes.get("tabindex")).toBe("-1");
    expect(styles.has("top")).toBe(false);
    fire("click");
    expect(clicks).toEqual(["new"]);
  });

  it("drops the listeners and hands the ref null on clear", () => {
    const { renderer, fire } = fakeRenderer();
    const refs: unknown[] = [];
    const clicks: string[] = [];
    const element = {} as HTMLElement;
    const applier = new TreePropsApplier(element, renderer);
    applier.apply({ ref: (el: unknown) => refs.push(el), onClick: () => clicks.push("x") });
    applier.clear();
    fire("click");
    expect(clicks).toEqual([]);
    expect(refs).toEqual([element, null]);
  });
});

import { NgTemplateOutlet } from "@angular/common";
import {
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  DestroyRef,
  Directive,
  effect,
  ElementRef,
  HostAttributeToken,
  inject,
  InjectionToken,
  Injector,
  input,
  Renderer2,
  TemplateRef,
} from "@angular/core";
import type { ItemInstance } from "@headless-tree/core";
import { NgIcon } from "@ng-icons/core";
import { lucideChevronDown, lucideChevronRight, lucideMinus, lucidePlus } from "@ng-icons/lucide";
import type { KoTreeHandle } from "@/ui/primitives/tree-adapter";
import {
  styleEntriesOf,
  TreePropsApplier,
  type TreeElementProps,
} from "@/ui/primitives/tree-props";
import { selectOnClick } from "@/ui/primitives/tree-select";
import { cn } from "@/ui/utils";

/** The item of the row an item template is rendered in. */
export const KO_TREE_ITEM = new InjectionToken<ItemInstance<unknown>>("KoTreeItem");

/** Keeps a props bag from headless-tree applied to an element, until it is destroyed. */
function bindProps(props: () => TreeElementProps | null): void {
  const element = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;
  const applier = new TreePropsApplier(element, inject(Renderer2));
  effect(() => {
    const next = props();
    if (next) applier.apply(next);
  });
  inject(DestroyRef).onDestroy(() => applier.clear());
}

/**
 * Spreads what `item.getProps()` (or any headless-tree props bag) returns onto its element:
 * attributes and ARIA, styles, the `onClick`-style handlers as DOM listeners, and the `ref`.
 */
@Directive({ selector: "[koTreeItemProps]" })
export class KoTreeItemProps {
  readonly koTreeItemProps = input.required<TreeElementProps>();

  constructor() {
    bindProps(() => this.koTreeItemProps());
  }
}

/**
 * The row template: `<ng-template koTreeItem let-item>`. Bind the tree handle,
 * `[koTreeItem]="tree"`, for a typed `item`.
 */
@Directive({ selector: "ng-template[koTreeItem]" })
export class KoTreeItem<T = unknown> {
  /** Only there to type `let-item`; a bare `koTreeItem` works the same. */
  readonly koTreeItem = input<KoTreeHandle<T> | "">("");
  readonly template = inject<TemplateRef<{ $implicit: ItemInstance<T> }>>(TemplateRef);

  static ngTemplateContextGuard<T>(
    _dir: KoTreeItem<T>,
    _ctx: unknown,
  ): _ctx is { $implicit: ItemInstance<T> } {
    return true;
  }
}

/** The line drawn where an ordered drop would land; nothing while no drag is over the tree. */
@Component({
  selector: "ko-tree-drag-line",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "contents" },
  template: `
    @if (lineStyle(); as style) {
      <div [style]="style" [class]="classes()"></div>
    }
  `,
})
export class KoTreeDragLine {
  readonly class = input<string>("");
  private readonly tree = inject(KoTree, { optional: true });

  protected readonly lineStyle = computed(() => {
    const handle = this.tree?.handle();
    if (!handle) return null;
    handle.items();
    const tree = handle.tree;
    if (typeof tree.getDragLineStyle !== "function") return null;
    const style = tree.getDragLineStyle() as Record<string, unknown> | undefined;
    if (!style || style["display"] === "none") return null;
    return styleEntriesOf(style);
  });

  protected readonly classes = computed(() =>
    cn("pointer-events-none z-20 h-0.5 bg-signal", this.class()),
  );
}

type TreeRow<T> = {
  item: ItemInstance<T>;
  props: TreeElementProps;
  padding: number;
  classes: string;
  injector: Injector;
};

/**
 * A tree over a handle from `injectTreeController`: the host is the `role="tree"`
 * container, and each visible item is a row rendered from the `koTreeItem` template.
 */
@Component({
  selector: "ko-tree",
  imports: [NgTemplateOutlet, KoTreeItemProps, KoTreeDragLine],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[class]": "classes()" },
  templateUrl: "./tree.component.html",
})
export class KoTree<T = unknown> {
  readonly handle = input.required<KoTreeHandle<T>>();
  readonly indent = input(12);
  readonly toggleIconType = input<"chevron" | "plus-minus">("chevron");
  readonly class = input<string>("");

  protected readonly itemTemplate = contentChild<KoTreeItem<T>>(KoTreeItem);
  private readonly injector = inject(Injector);
  private readonly label = inject(new HostAttributeToken("aria-label"), { optional: true });
  private readonly injectors = new Map<string, Injector>();

  protected readonly classes = computed(() => cn("relative flex flex-col", this.class()));

  protected readonly rows = computed<TreeRow<T>[]>(() => {
    const indent = this.indent();
    return this.handle()
      .items()
      .map((item) => {
        // The row's own click replaces headless-tree's, which would also toggle the folder.
        const props = {
          ...(item.getProps() as TreeElementProps),
          onClick: (event: MouseEvent) => this.onRowClick(item, event),
        };
        return {
          item,
          props,
          padding: indent * item.getItemMeta().level + 8,
          classes: cn(
            "group flex min-h-8 items-stretch gap-0.5 rounded-md pr-1 text-sm outline-none",
            item.isSelected?.() && "bg-secondary",
            // Nest-into-folder only — ordered drops use the drag line, not row fill/opacity.
            item.isUnorderedDragTarget?.() &&
              item.isFolder() &&
              "bg-signal/5 ring-1 ring-inset ring-signal/30",
          ),
          injector: this.injectorFor(item),
        };
      });
  });

  constructor() {
    bindProps(() => this.handle().tree.getContainerProps(this.label ?? undefined));
  }

  private onRowClick(item: ItemInstance<T>, event: MouseEvent): void {
    if (event.defaultPrevented) return;
    // Ignore bubbled clicks — label, chevron and drag handle handle their own.
    if (event.target !== event.currentTarget) return;
    selectOnClick(item, event);
    item.setFocused();
    item.getTree().updateDomFocus();
    item.primaryAction();
  }

  /** One injector per item id, so a row's template is not re-created on every change. */
  private injectorFor(item: ItemInstance<T>): Injector {
    const id = item.getId();
    let injector = this.injectors.get(id);
    if (!injector) {
      injector = Injector.create({
        providers: [{ provide: KO_TREE_ITEM, useValue: item }],
        parent: this.injector,
      });
      this.injectors.set(id, injector);
    }
    return injector;
  }
}

/**
 * The label of a row: a chevron (or plus/minus) that opens and closes a folder, then the
 * projected content, or the item's name. Without `item`, it labels the row it sits in.
 */
@Component({
  selector: "ko-tree-item-label",
  imports: [NgIcon],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "contents" },
  template: `
    @if (view(); as view) {
      <button type="button" tabindex="-1" [class]="classes()" (click)="onClick($event)">
        <span
          data-tree-toggle=""
          class="grid size-6 shrink-0 place-items-center text-muted-foreground"
        >
          @if (view.icon; as icon) {
            <ng-icon aria-hidden="true" size="0.875rem" [svg]="icon" />
          } @else {
            <span class="size-3.5"></span>
          }
        </span>
        <ng-content
          ><span class="truncate">{{ view.name }}</span></ng-content
        >
      </button>
    }
  `,
})
export class KoTreeItemLabel<T = unknown> {
  readonly item = input<ItemInstance<T>>();
  readonly class = input<string>("");

  private readonly tree = inject<KoTree<T>>(KoTree, { optional: true });
  private readonly rowItem = inject(KO_TREE_ITEM, { optional: true }) as ItemInstance<T> | null;

  private readonly node = computed(() => this.item() ?? this.rowItem);

  protected readonly view = computed(() => {
    // Read the items so a change in the tree's state re-reads the node.
    this.tree?.handle().items();
    const node = this.node();
    if (!node) return null;
    const folder = node.isFolder();
    const expanded = folder && node.isExpanded();
    const plusMinus = this.tree?.toggleIconType() === "plus-minus";
    const icon = !folder
      ? null
      : plusMinus
        ? expanded
          ? lucideMinus
          : lucidePlus
        : expanded
          ? lucideChevronDown
          : lucideChevronRight;
    return { name: node.getItemName(), icon };
  });

  protected readonly classes = computed(() =>
    cn("flex min-h-8 min-w-0 flex-1 items-center gap-2 self-stretch text-left", this.class()),
  );

  protected onClick(event: MouseEvent): void {
    const node = this.node();
    if (!node) return;
    // The chevron opens and closes a folder, and does nothing else; on a file it is the label.
    const toggle = (event.target as Element | null)?.closest?.("[data-tree-toggle]");
    if (toggle && node.isFolder()) {
      event.stopPropagation();
      if (node.isExpanded()) node.collapse();
      else node.expand();
      return;
    }
    event.stopPropagation();
    node.setFocused();
    node.getTree().updateDomFocus();
    if (event.defaultPrevented) return;
    selectOnClick(node, event);
    node.primaryAction();
  }
}

